@Test
public void testDeprecated_handlerTriggered() {
    assertDoesNotThrow(() -> {
        final Set<Option> handler = new HashSet<>();
        parser = DefaultParser.builder()
                .setDeprecatedHandler(handler::add)
                .build();

        final Option opt1 = Option.builder()
                .option("d1")
                .deprecated()
                .build();

        final Option opt2 = Option.builder()
                .option("d2")
                .deprecated(DeprecatedAttributes.builder()
                        .setForRemoval(true)
                        .setSince("1.0")
                        .setDescription("Do this instead.")
                        .get())
                .build();

        final CommandLine cl = parser.parse(new Options()
                .addOption(opt1)
                .addOption(opt2), new String[] {"-d1", "-d2"});

        assertTrue(cl.hasOption(opt1.getOpt()), "Parser should recognize option d1");
        assertTrue(cl.hasOption(opt2.getOpt()), "Parser should recognize option d2");
        assertTrue(handler.contains(opt1), "Deprecated handler should be invoked for opt1");
        assertTrue(handler.contains(opt2), "Deprecated handler should be invoked for opt2");
    }, "Unexpected exception thrown while testing deprecated handler triggering");
}

@Test
public void testDeprecated_handlerNotTriggeredForNonDeprecatedOption() {
    assertDoesNotThrow(() -> {
        final Set<Option> handler = new HashSet<>();
        parser = DefaultParser.builder()
                .setDeprecatedHandler(handler::add)
                .build();

        final Option optDeprecated = Option.builder()
                .option("d1")
                .deprecated()
                .build();

        final Option optNonDeprecated = Option.builder()
                .option("a")
                .build();

        final CommandLine cl = parser.parse(new Options()
                .addOption(optDeprecated)
                .addOption(optNonDeprecated), new String[] {"-d1", "-a"});

        assertTrue(cl.hasOption(optDeprecated.getOpt()), "Parser should recognize deprecated option d1");
        assertTrue(cl.hasOption(optNonDeprecated.getOpt()), "Parser should recognize non‑deprecated option a");
        assertTrue(handler.contains(optDeprecated), "Deprecated handler should be invoked for deprecated option");
        assertFalse(handler.contains(optNonDeprecated), "Deprecated handler should not be invoked for non‑deprecated option");
    }, "Unexpected exception thrown while testing deprecated handler non‑triggering");
}

