    assertThat(list.lastIndexOf(new JsonPrimitive(2)))
        .named("lastIndexOf JsonPrimitive(2) should be -1")
        .isEqualTo(-1);
    assertThat(list.lastIndexOf(null))
        .named("lastIndexOf null should be -1")
        .isEqualTo(-1);
