    Document doc = Jsoup.parse("<div class=foo>Text</div>");
    Element original = doc.select("div").first();
    Element clone = doc.clone().select("div").first();

    original.removeClass("foo");
    original.text("None");

    assertFalse("Original element should no longer have class 'foo' after removal", original.hasClass("foo"));
    assertEquals("Original element's text should be updated to 'None'", "None", original.text());
    assertTrue("Cloned element should still have class 'foo' after original modification", clone.hasClass("foo"));
    assertEquals("Cloned element's text should remain unchanged after original modification", "Text", clone.text());
}

