private static final int EXPECTED_ATTRIBUTE_COUNT = 3;
private static final List<String> EXPECTED_VALUES = List.of("1", "2", "3");

private Attributes createAttributes() {
    Attributes a = new Attributes();
    a.put("Tot", "1");
    a.put("Hello", "2");
    a.put("data-name", "3");
    return a;
}

@Test
public void testAttributesSize() {
    Attributes a = createAttributes();
    assertEquals(EXPECTED_ATTRIBUTE_COUNT, a.size(),
            "Attributes should contain the expected number of entries");
}

@Test
@EnabledIf("isIterationValid")
public void testAttributesIterationValues() {
    Attributes a = createAttributes();
    List<String> actualValues = StreamSupport.stream(a.spliterator(), false)
            .map(Attribute::getValue)
            .collect(Collectors.toList());
    assertIterableEquals(EXPECTED_VALUES, actualValues,
            "Iterator should return values in the order they were added");
}

/**
 * Helper method used by @EnabledIf to verify that the iterator can be traversed.
 * Returns true if the iterator yields the expected number of elements.
 */
private boolean isIterationValid() {
    Attributes a = createAttributes();
    long count = StreamSupport.stream(a.spliterator(), false).count();
    return count == EXPECTED_ATTRIBUTE_COUNT;
}

