@Test
public void createsFormData() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
            "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
            "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
            "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
            "<input name='ten' value='text' disabled>" +
            "<input name='eleven' value='text' type='button'>" +
            "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    int expectedSize = 6;
    assertEquals("Form should contain the expected number of key/value pairs", expectedSize, data.size());

    String actual0 = data.get(0).toString();
    assertEquals("First entry should be the input field 'one' with value 'two'", "one=two", actual0);

    String actual1 = data.get(1).toString();
    assertEquals("Second entry should be the selected option 'four' for select 'three'", "three=four", actual1);

    String actual2 = data.get(2).toString();
    assertEquals("Third entry should be the selected option 'five' for select 'three'", "three=five", actual2);

    String actual3 = data.get(3).toString();
    assertEquals("Fourth entry should be textarea 'six' with value 'seven'", "six=seven", actual3);

    String actual4 = data.get(4).toString();
    assertEquals("Fifth entry should be the checked radio button 'seven' with value 'on'", "seven=on", actual4);

    String actual5 = data.get(5).toString();
    assertEquals("Sixth entry should be the default-checked checkbox 'eight' with value 'on'", "eight=on", actual5);
}

